function guidePage() {
  const checks = [
    ['Start with the business goal', 'Write down what the website must help people do: understand your offer, enquire, buy, compare products or use a service. A clear goal helps you evaluate a proposal beyond visual style.'],
    ['Ask how discovery works', 'A good partner should ask about audiences, existing content, competitors, internal workflows and what success would look like. Ask what decisions will be made before design begins.'],
    ['Check what the scope includes', 'Confirm whether content planning, responsive design, accessibility, SEO foundations, analytics, CMS training, integrations, testing and launch support are included. These are easy to assume and expensive to discover late.'],
    ['Discuss ownership and handover', 'Know who owns the domain, source code, design files and content. Ask how your team will update pages, what documentation you receive and how changes will be handled after launch.'],
    ['Review performance and quality plans', 'Ask how the team tests mobile journeys, page speed, forms, accessibility and search crawlability. Agree on the devices and important pages to test before launch.'],
    ['Compare the full partnership', 'The lowest quote may omit content, migration or ongoing care. Compare the assumptions, people, milestones and support behind each estimate, not just the final number.']
  ];
  const main = `${hero({crumb:'Guide / Choosing a web partner',eyebrowText:'A PRACTICAL BUYER GUIDE',title:'How to choose a web development company',accent:'in India.',intro:'A useful checklist for teams comparing web development partners in India. Use it to ask better questions, define the scope and make a confident choice.',visual:'service'})}
  <section class="section"><div class="shell guide-intro"><div>${eyebrow('THE DECISION')}<h2>Choose for the site you <em>actually need.</em></h2></div><div><p>A company website, e-commerce store and customer portal call for different skills. Before shortlisting agencies, identify the audience, the main actions visitors should take and the systems the site may need to connect to.</p><p>Use the questions below in every conversation. They help make proposals more comparable and reveal how a team will handle the work after the first design presentation.</p><p class="guide-date">Published 30 October 2026 · Klirolabs</p></div></div></section>
  <section class="section tinted-section"><div class="shell">${sectionHead('SIX THINGS TO CHECK','A practical evaluation <em>checklist.</em>')}<div class="guide-list">${checks.map(([heading,body],index)=>`<article><span>${String(index+1).padStart(2,'0')} /</span><div><h3>${esc(heading)}</h3><p>${esc(body)}</p></div></article>`).join('')}</div></div></section>
  <section class="section"><div class="shell guide-intro"><div>${eyebrow('BUDGET AND TIMELINE')}<h2>Understand what drives <em>the estimate.</em></h2></div><div><p>Website development costs in India vary with the number of page types, the quality and readiness of content, custom design, CMS needs, integrations, e-commerce requirements, data migration, accessibility work and the approval process. A useful estimate explains these assumptions rather than giving a single unexplained number.</p><p>Ask for a staged plan with clear review points. A focused first release can be better than an oversized launch when requirements are still changing. Reserve time for content entry, testing, redirects and handover.</p>${link(servicePath('enterprise-web-development'),'Explore our web development service','text-arrow')}</div></div></section>
  <section class="section faq-section"><div class="shell faq-grid"><div>${eyebrow('BEFORE YOU SIGN')}<h2>Questions worth asking every agency.</h2></div><div>${[
    ['Who owns the website and its source code?', 'Confirm ownership of the domain, repository, design files, content and hosting account in the agreement.'],
    ['Can our team update it after launch?', 'Ask for a demonstration of the editing experience and clarify who handles new pages, fixes and maintenance.'],
    ['How will we measure whether it works?', 'Agree on meaningful outcomes such as qualified enquiries, completed purchases or successful user tasks, then make sure the site can measure them.']
  ].map(([q,a])=>`<details class="faq-item"><summary>${esc(q)} <span>+</span></summary><p>${esc(a)}</p></details>`).join('')}</div></div></section>${callout('Have a website brief in mind?','Tell us what the site needs to achieve. We can help turn an early idea into a clear scope and practical next step.')}`;
  return layout({path:guidePath,title:'How to Choose a Web Development Company in India | Klirolabs',description:'A practical checklist for choosing a web development company in India: scope, ownership, performance, cost factors and questions to ask before you hire.',main,kind:'guide'});
}

